"""Execute loaded hooks at an insertion point."""

from __future__ import annotations

import asyncio
import threading
import time
from queue import Queue
from typing import NamedTuple, TypeVar

import structlog

from rasa.mantle.hooks.constants import (
    FAIL_CLOSED,
    FAIL_OPEN,
    LOG_HOOK_EXECUTION,
    LOG_MODIFY_CONTROL_FLOW_DISCARDED,
    LOG_OBSERVER_CONTROL_FLOW_DISCARDED,
    LOG_OBSERVER_ERROR,
    LOG_OBSERVER_TIMEOUT,
)
from rasa.mantle.hooks.exceptions import (
    HookControlFlow,
    HookExecutionError,
    HookRejection,
    RetryModel,
)
from rasa.mantle.hooks.payloads import HookPayload
from rasa.mantle.hooks.points import spec_for_point
from rasa.mantle.hooks.registry import HookRegistry, RegisteredHook
from rasa.mantle.hooks.types import (
    MODIFY_LANE,
    OBSERVE_LANE,
    OUTCOME_ERROR,
    OUTCOME_REJECTION,
    OUTCOME_RETRY,
    OUTCOME_SUCCESS,
    OUTCOME_TIMEOUT,
    FailPolicy,
    HookOutcome,
)
from rasa.telemetry import is_telemetry_enabled, track_maestro_hook_executed

structlogger = structlog.get_logger(__name__)

PayloadT = TypeVar("PayloadT", bound=HookPayload)

# Strong references so fire-and-forget observer batches are not garbage-collected.
_pending_observer_batches: set[asyncio.Task[None]] = set()

_TELEMETRY_SEND_WORKERS = 2
_TELEMETRY_QUEUE_SIZE = 64

_CONTROL_SIGNAL_OUTCOMES: tuple[tuple[type[HookControlFlow], HookOutcome], ...] = (
    (HookRejection, OUTCOME_REJECTION),
    (RetryModel, OUTCOME_RETRY),
)


class ModifyResult(NamedTuple):
    """Outcome of awaiting a modify hook."""

    payload: HookPayload
    control_flow: HookControlFlow | None = None
    outcome: HookOutcome = OUTCOME_SUCCESS


class _HookTelemetryEvent(NamedTuple):
    point: str
    lane: str
    outcome: HookOutcome
    duration_ms: float
    timeout_ms: int
    fail_policy: FailPolicy | None
    is_voice: bool | None
    observer_count: int | None


_telemetry_queue: Queue[_HookTelemetryEvent] = Queue(_TELEMETRY_QUEUE_SIZE)
_telemetry_workers_started = False
_telemetry_workers_lock = threading.Lock()


def preserve_identity(original: PayloadT, returned: PayloadT) -> PayloadT:
    """Keep engine-owned identity fields from the input payload."""
    return returned.model_copy(
        update={
            "sender_id": original.sender_id,
            "call": original.call.model_copy(deep=True),
            "channel": original.channel.model_copy(deep=True),
        }
    )


def _payload_is_voice(payload: HookPayload | None) -> bool | None:
    if payload is None:
        return None
    value = getattr(payload, "is_voice", None)
    return value if isinstance(value, bool) else None


def _telemetry_worker(queue: Queue[_HookTelemetryEvent]) -> None:
    while True:
        event = queue.get()
        try:
            track_maestro_hook_executed(
                point=event.point,
                lane=event.lane,
                outcome=event.outcome,
                duration_ms=event.duration_ms,
                timeout_ms=event.timeout_ms,
                fail_policy=event.fail_policy,
                is_voice=event.is_voice,
                observer_count=event.observer_count,
            )
        except Exception:
            pass
        finally:
            queue.task_done()


def _ensure_telemetry_workers() -> None:
    global _telemetry_workers_started
    if _telemetry_workers_started:
        return
    with _telemetry_workers_lock:
        if _telemetry_workers_started:
            return
        started = 0
        for index in range(_TELEMETRY_SEND_WORKERS):
            try:
                threading.Thread(
                    target=_telemetry_worker,
                    args=(_telemetry_queue,),
                    name=f"mantle-hook-telemetry-{index}",
                    daemon=True,
                ).start()
                started += 1
            except Exception:
                if started == 0:
                    raise
                break
        _telemetry_workers_started = True


def _emit_hook_telemetry(
    hook: RegisteredHook,
    lane: str,
    outcome: HookOutcome,
    duration_ms: float,
    *,
    payload: HookPayload | None,
    fail_policy: FailPolicy | None,
    observer_count: int | None,
) -> None:
    """Queue telemetry without waiting for its result, response, or errors."""
    try:
        if not is_telemetry_enabled():
            return
        _ensure_telemetry_workers()
        _telemetry_queue.put_nowait(
            _HookTelemetryEvent(
                point=hook.point,
                lane=lane,
                outcome=outcome,
                duration_ms=duration_ms,
                timeout_ms=hook.timeout_ms,
                fail_policy=fail_policy,
                is_voice=_payload_is_voice(payload),
                observer_count=observer_count,
            )
        )
    except Exception:
        pass


def _log_hook_execution(
    hook: RegisteredHook,
    lane: str,
    outcome: HookOutcome,
    started: float,
    *,
    payload: HookPayload | None = None,
    fail_policy: FailPolicy | None = None,
    observer_count: int | None = None,
) -> None:
    duration_ms = round((time.perf_counter() - started) * 1000, 2)
    structlogger.info(
        LOG_HOOK_EXECUTION,
        point=hook.point,
        lane=lane,
        outcome=outcome,
        duration_ms=duration_ms,
        hook_name=hook.func.__name__,
    )
    _emit_hook_telemetry(
        hook,
        lane,
        outcome,
        duration_ms,
        payload=payload,
        fail_policy=fail_policy,
        observer_count=observer_count,
    )


def _observer_failure(hook: RegisteredHook, exc: BaseException) -> HookOutcome:
    fields = {
        "point": hook.point,
        "hook_name": hook.func.__name__,
        "error_type": type(exc).__name__,
    }
    if isinstance(exc, HookControlFlow):
        structlogger.warning(LOG_OBSERVER_CONTROL_FLOW_DISCARDED, **fields)
        return OUTCOME_ERROR
    if isinstance(exc, asyncio.TimeoutError):
        structlogger.warning(LOG_OBSERVER_TIMEOUT, **fields, timeout_ms=hook.timeout_ms)
        return OUTCOME_TIMEOUT
    structlogger.warning(LOG_OBSERVER_ERROR, **fields)
    structlogger.debug(LOG_OBSERVER_ERROR, **fields, exc_info=exc)
    return OUTCOME_ERROR


async def _run_observer(
    hook: RegisteredHook, payload: HookPayload, observer_count: int
) -> None:
    started = time.perf_counter()
    outcome: HookOutcome = OUTCOME_SUCCESS
    try:
        await asyncio.wait_for(hook.func(payload), timeout=hook.timeout_ms / 1000)
    except Exception as exc:
        outcome = _observer_failure(hook, exc)
    finally:
        _log_hook_execution(
            hook,
            OBSERVE_LANE,
            outcome,
            started,
            payload=payload,
            fail_policy=FAIL_OPEN,
            observer_count=observer_count,
        )


async def _run_observer_batch(
    pairs: list[tuple[RegisteredHook, HookPayload]],
) -> None:
    observer_count = len(pairs)
    await asyncio.gather(
        *(_run_observer(hook, snapshot, observer_count) for hook, snapshot in pairs)
    )


def run_observers(
    registry: HookRegistry, point: str, payload: PayloadT
) -> asyncio.Task[None] | None:
    """Schedule observe-lane hooks concurrently without blocking the turn.

    Engine call sites must fire-and-forget this function (do not await it).
    The returned task is only for tests that need to wait for completion.
    """
    observers = registry.observers(point)
    if not observers:
        return None

    pairs = [(hook, payload.model_copy(deep=True)) for hook in observers]
    batch = asyncio.create_task(
        _run_observer_batch(pairs),
        name=f"hook-observe-batch-{point}",
    )
    _pending_observer_batches.add(batch)
    batch.add_done_callback(_pending_observer_batches.discard)
    return batch


def _control_signal_outcome(point: str, signal: HookControlFlow) -> HookOutcome | None:
    allowed = spec_for_point(point).allowed_control_signals
    for signal_type, outcome in _CONTROL_SIGNAL_OUTCOMES:
        if isinstance(signal, signal_type):
            return outcome if signal_type in allowed else None
    return None


def _handle_modify_failure(
    payload: PayloadT,
    fail_policy: FailPolicy,
    outcome: HookOutcome,
    reason: str,
) -> ModifyResult:
    if fail_policy != FAIL_CLOSED:
        return ModifyResult(payload=payload, outcome=outcome)
    raise HookExecutionError(reason)


async def run_modify(
    registry: HookRegistry, point: str, payload: PayloadT
) -> ModifyResult:
    """Await the single modify hook for *point*, if registered."""
    hook = registry.modifier(point)
    if hook is None:
        return ModifyResult(payload=payload)

    fail_policy = spec_for_point(point).fail_policy_modify or FAIL_CLOSED
    started = time.perf_counter()
    working = payload.model_copy(deep=True)

    def record(outcome: HookOutcome) -> None:
        _log_hook_execution(
            hook,
            MODIFY_LANE,
            outcome,
            started,
            payload=payload,
            fail_policy=fail_policy,
        )

    def abort(outcome: HookOutcome, detail: str) -> ModifyResult:
        record(outcome)
        return _handle_modify_failure(
            payload,
            fail_policy,
            outcome,
            f"Modify hook {hook.func.__name__!r} for point {point!r} {detail}",
        )

    try:
        result: object = await asyncio.wait_for(
            hook.func(working), timeout=hook.timeout_ms / 1000
        )
    except HookControlFlow as signal:
        # Intentional veto/retry from the hook (HookRejection, RetryModel, …).
        # Unsupported signals are discarded so they cannot acquire veto semantics.
        outcome = _control_signal_outcome(point, signal)
        if outcome is None:
            structlogger.warning(
                LOG_MODIFY_CONTROL_FLOW_DISCARDED,
                point=point,
                hook_name=hook.func.__name__,
                error_type=type(signal).__name__,
            )
            record(OUTCOME_ERROR)
            return ModifyResult(payload=payload, outcome=OUTCOME_ERROR)
        # Allowed signal: surface it to the engine via ModifyResult.control_flow.
        record(outcome)
        return ModifyResult(payload=payload, control_flow=signal, outcome=outcome)
    except asyncio.TimeoutError:
        # Hook exceeded timeout_ms; fail-open keeps input, fail-closed raises.
        return abort(OUTCOME_TIMEOUT, f"timed out after {hook.timeout_ms} ms.")
    except HookExecutionError:
        # Already a typed hook failure from validation; log and re-raise as-is.
        record(OUTCOME_ERROR)
        raise
    except Exception as exc:
        # Unexpected crash in the hook; honor fail_policy via abort().
        return abort(OUTCOME_ERROR, f"failed with {type(exc).__name__}.")

    # Validate outside the try so fail-closed HookExecutionError from abort()
    # is not swallowed by ``except Exception``. Fail-open points keep the
    # original payload instead of aborting the turn on a bad return value.
    if not isinstance(result, type(payload)):
        return abort(
            OUTCOME_ERROR,
            f"returned {type(result)!r}, expected {type(payload)!r}.",
        )
    record(OUTCOME_SUCCESS)
    return ModifyResult(payload=preserve_identity(payload, result))
